<template><view class="credit"><text class="heading">赊购额度与还款</text><view v-if="error">{{error}}<button class="ui-button" @click="load">重试</button></view><template v-if="account"><view class="card"><view>批准额度 ¥{{money(account.credit_limit)}}</view><view>已占用 ¥{{money(account.occupied)}}</view><view>可用额度 ¥{{money(account.available)}}</view><text class="hint">新订单账期 {{account.term_days}} 天。等待核销的还款不会提前释放额度。</text></view><button class="ui-button" v-if="canPay&&account.bills.some(b=>b.state==='active'&&b.outstanding>0)" :disabled="busy" @click="selectOldest">按最早到期顺序还款</button><view v-for="b in account.bills" :key="b.order_id" class="card"><view>订单 {{b.order_no}}</view><view>{{b.state==='reserved'?'待确认，预占额度':b.state==='cancelled'?'订单已关闭':'剩余应还'}} ¥{{money(b.state==='reserved'?b.amount:b.state==='cancelled'?0:b.outstanding)}}</view><view v-if="b.due_at">还款日期：{{b.due_at}}</view><view v-if="b.overdue&&b.outstanding>0" class="danger">已逾期，请尽快还款并等待财务核销。</view><button class="ui-button" v-if="b.state==='active'&&b.outstanding>0&&canPay" :disabled="busy" @click="select(b)">登记本单还款</button></view><text v-if="!account.bills.length" class="hint">还没有账期采购记录。</text><view v-if="selected" class="card"><text class="heading">提交还款凭证</text><view>订单 {{selected.order_no}}</view><template v-if="account.bank.enabled"><view>收款户名：{{account.bank.companyName}}</view><view>银行：{{account.bank.bankName}}</view><view selectable>账号：{{account.bank.accountNumber}}</view></template><text v-else class="hint">商家暂未公布收款账户，请先联系财务确认，勿向不明账户转账。</text><input :disabled="busy" v-model="payer" placeholder="转账户名"/><input :disabled="busy" v-model="amount" type="digit" placeholder="本次还款金额（元）"/><button class="ui-button" :disabled="busy" @click="choose">{{proof?'已上传凭证，点击重选':'上传还款凭证图片'}}</button><button class="ui-button" :disabled="busy||!proof" @click="submit">提交财务核销</button><button class="ui-button" :disabled="busy" @click="selected=null">暂不提交</button></view><view v-for="r in account.repayments" :key="r.id" class="card"><view>还款 ¥{{money(r.amount)}} · {{states[r.status]}}</view><view v-if="r.note">{{r.note}}</view></view></template></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,money,notify,uploadTransferProof,getToken} from '../services/shop.js'
export default {
 mixins:[refreshOnTick()],props:{canPay:Boolean},data(){return {account:null,error:'',selected:null,payer:'',amount:'',proof:'',key:'',busy:false,states:{pending:'待核销',confirmed:'已核销',rejected:'已退回补资料'}}},mounted(){this.load()},
 methods:{money,selectOldest(){if(this.busy)return;this.select({order_id:0,order_no:'按最早到期顺序核销',outstanding:this.account.bills.filter(b=>b.state==='active').reduce((n,b)=>n+b.outstanding,0)})},async load(){try{this.account=await request('/company/credit');this.error=''}catch(e){this.error=e.message}},
  async act(fn){if(this.busy)return;this.busy=true;try{await fn();await this.load()}catch(e){notify(e)}finally{this.busy=false}},
  select(b){if(this.busy)return;this.selected=b;this.amount=money(b.outstanding);this.proof='';this.key=''},
  choose(){return this.act(async()=>{if(!this.selected)throw Error('请先选择还款账单');const id=this.selected.order_id,token=getToken();const file=await new Promise((resolve,reject)=>uni.chooseImage({count:1,sizeType:['compressed'],success:r=>resolve(r.tempFilePaths[0]),fail:e=>/cancel/i.test(e.errMsg||'')?resolve(null):reject(Error('选图失败，请重试'))}));if(!file)return;const proof=await uploadTransferProof(file);if(this._panelRefreshDisposed||this.selected?.order_id!==id||getToken()!==token)throw Error('还款对象已变化，请重新选择凭证');this.proof=proof;this.key=''})},
  submit(){return this.act(async()=>{if(!this.selected||!this.proof)throw Error('请先选择账单并上传还款凭证');if(!/^\d+(\.\d{1,2})?$/.test(this.amount)||Number(this.amount)<=0)throw Error('金额最多两位小数且大于0');if(!this.key)this.key='repay_'+Date.now()+'_'+Math.random().toString(36).slice(2);const id=this.selected.order_id,token=getToken();await request('/company/credit/repay','POST',{orderId:id,payer:this.payer,amount:Math.round(Number(this.amount)*100),proof:this.proof,requestKey:this.key});if(this._panelRefreshDisposed||this.selected?.order_id!==id||token!==getToken())return;this.selected=null;this.key='';this.proof='';uni.showToast({title:'已提交，等待核销',icon:'none'})})}
 }
}
</script>
<style scoped>
@import '../styles/component-base.css';
.credit{font-size:16px}.heading{display:block;font-size:20px;font-weight:bold}.card{background:var(--shop-surface, #fdfeff);border-radius:12px;padding:16px;line-height:1.8;margin:12px 0;overflow-wrap:anywhere}.hint{display:block;font-size:14px;color:var(--shop-ink, #28546c)}.danger{color:#a53124}input{margin:12px 0;padding:12px;background:var(--shop-background, #f3f8fb)}button{margin-top:12px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);font-size:16px}</style>
